    result = []
    for start, end in sorted(intervals):
        if result and start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)
        else:
            result.append([start, end])
    return result


def duration(intervals):
    return sum(end - start for start, end in intervals)


def intersection(left, right):
    total = 0
    i = j = 0
    while i < len(left) and j < len(right):
        total += max(0, min(left[i][1], right[j][1]) - max(left[i][0], right[j][0]))
        if left[i][1] <= right[j][1]:
            i += 1
        else:
            j += 1
    return total


def profile_file(prefix):
    filesystem, root = fsspec.core.url_to_fs(prefix)
    matches = filesystem.glob(root.rstrip("/") + "/**/*.xplane.pb")
    candidates = []
    for path in matches:
        space = _xspace_message_class()()
        with filesystem.open(path, "rb") as source:
            space.ParseFromString(source.read())
        if any(plane.name == "/device:GPU:0" for plane in space.planes):
            candidates.append((path, space))
    if len(candidates) != 1:
        raise RuntimeError(f"Expected one GPU0 XPlane under {prefix}, found {[path for path, _ in candidates]}")
