        by_group[group(row["name"])].append(interval)
        by_kernel[row["name"]].append(interval)
    unions = {name: merged(intervals) for name, intervals in by_group.items()}
    groups = []
    for name, intervals in sorted(by_group.items(), key=lambda item: -duration(item[1])):
        union = unions[name]
