import json
import sys

import fsspec
from marin.profiling.xplane import _xspace_message_class

MAX_OUTPUT_BYTES = 100_000


def varint(data, position):
    value = 0
    shift = 0
    while True:
        byte = data[position]
        position += 1
        value |= (byte & 0x7F) << shift
        if not byte & 0x80:
            return value, position
        shift += 7


def fields(data):
    position = 0
    result = []
    while position < len(data):
        tag, position = varint(data, position)
        number, wire = tag >> 3, tag & 7
        if wire == 0:
            value, position = varint(data, position)
        elif wire == 1:
            value = data[position : position + 8]
            position += 8
        elif wire == 2:
            length, position = varint(data, position)
            value = data[position : position + length]
            position += length
        elif wire == 5:
            value = data[position : position + 4]
            position += 4
        else:
            raise ValueError(f"unsupported wire type {wire}")
        result.append((number, wire, value))
    return result


def one(items, number, default=None):
    values = [value for field, _, value in items if field == number]
    if not values:
        return default
    if len(values) != 1:
        raise ValueError(f"expected one field {number}, found {len(values)}")
    return values[0]


def many(items, number):
    return [value for field, _, value in items if field == number]


def text(value):
    return value.decode() if value is not None else ""


def packed_ints(items, number):
    result = []
    for field, wire, value in items:
        if field != number:
            continue
        if wire == 0:
            result.append(value)
        elif wire == 2:
            position = 0
            while position < len(value):
                item, position = varint(value, position)
                result.append(item)
        else:
            raise ValueError((number, wire))
    return result


def training_hlo(space):
    matches = []
    for plane in space.planes:
        if plane.name != "/host:metadata":
            continue
        for metadata in plane.event_metadata.values():
            if not metadata.name.startswith("jit_train_step("):
                continue
            payloads = [stat.bytes_value for stat in metadata.stats if stat.bytes_value]
            if len(payloads) == 1:
                matches.append((metadata.name, payloads[0]))
    if len(matches) != 1:
        raise ValueError(f"expected one jit_train_step HloProto, found {[name for name, _ in matches]}")
    return matches[0]


def schedule_summary(module_items):
    payload = one(module_items, 7)
    if payload is None:
        return {"present": False, "sequence_count": 0, "scheduled_instruction_ids": 0}
    entries = many(fields(payload), 1)
    scheduled = 0
    for entry in entries:
        entry_items = fields(entry)
        sequence = one(entry_items, 2)
        if sequence is not None:
            scheduled += len(packed_ints(fields(sequence), 1))
    return {"present": True, "sequence_count": len(entries), "scheduled_instruction_ids": scheduled}


def analyze(path):
    space = _xspace_message_class()()
    with fsspec.open(path, "rb") as source:
        space.ParseFromString(source.read())
    metadata_name, hlo = training_hlo(space)
    hlo_items = fields(hlo)
    module_payload = one(hlo_items, 1)
    assignment_payload = one(hlo_items, 3)
    if module_payload is None:
        raise ValueError("HloProto field 1 HloModuleProto is absent")
    module_items = fields(module_payload)
    opcode_counts = collections.Counter()
    custom_call_targets = collections.Counter()
    remat_prefixes = collections.Counter()
    computations = many(module_items, 3)
    instruction_count = 0
    for computation in computations:
        for instruction in many(fields(computation), 2):
            instruction_items = fields(instruction)
            name = text(one(instruction_items, 1))
            opcode = text(one(instruction_items, 2))
            opcode_counts[opcode] += 1
            instruction_count += 1
            if opcode == "custom-call":
                custom_call_targets[text(one(instruction_items, 28)) or "<missing>"] += 1
            if ".remat" in name:
                remat_prefixes[name.split(".remat", 1)[0]] += 1
    color_totals = collections.defaultdict(lambda: {"allocations": 0, "bytes": 0})
    allocation_count = 0
    if assignment_payload is not None:
        for allocation in many(fields(assignment_payload), 3):
            allocation_items = fields(allocation)
            color = str(one(allocation_items, 8, 0))
            color_totals[color]["allocations"] += 1
            color_totals[color]["bytes"] += one(allocation_items, 2, 0)
            allocation_count += 1
    return {
        "source": path,
        "metadata_name": metadata_name,
        "hlo_proto_bytes": len(hlo),
        "hlo_proto_sha256": hashlib.sha256(hlo).hexdigest(),
        "computations": len(computations),
        "instructions": instruction_count,
        "opcode_counts": dict(sorted(opcode_counts.items())),
        "custom_call_target_counts": dict(sorted(custom_call_targets.items())),
        "remat_name_count": sum(remat_prefixes.values()),
        "remat_prefix_counts": dict(sorted(remat_prefixes.items())),
        "schedule": schedule_summary(module_items),
        "async_counts": {"start": opcode_counts["async-start"], "done": opcode_counts["async-done"]},
        "buffer_assignment_present": assignment_payload is not None,
        "allocation_count": allocation_count,
        "allocation_size_totals_by_color": dict(sorted(color_totals.items())),
    }


def counter_diff(control, treatment, field):
    left = control[field]
    right = treatment[field]
    return {key: right.get(key, 0) - left.get(key, 0) for key in sorted(set(left) | set(right)) if right.get(key, 0) != left.get(key, 0)}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("control_xplane")
    parser.add_argument("treatment_xplane")
    args = parser.parse_args()
    control = analyze(args.control_xplane)
    treatment = analyze(args.treatment_xplane)
    result = {
        "schema": "hero2_slop_hlo_probe/v1",
        "control": control,
        "treatment": treatment,
        "diff_treatment_minus_control": {
            "computations": treatment["computations"] - control["computations"],
            "instructions": treatment["instructions"] - control["instructions"],
            "opcode_counts": counter_diff(control, treatment, "opcode_counts"),
            "custom_call_target_counts": counter_diff(control, treatment, "custom_call_target_counts"),
            "remat_prefix_counts": counter_diff(control, treatment, "remat_prefix_counts"),
            "allocation_size_totals_by_color": {
                color: {
                    "allocations": treatment["allocation_size_totals_by_color"].get(color, {}).get("allocations", 0) - control["allocation_size_totals_by_color"].get(color, {}).get("allocations", 0),
                    "bytes": treatment["allocation_size_totals_by_color"].get(color, {}).get("bytes", 0) - control["allocation_size_totals_by_color"].get(color, {}).get("bytes", 0),
                }
                for color in sorted(set(control["allocation_size_totals_by_color"]) | set(treatment["allocation_size_totals_by_color"]))
            },
        },
        "limitations": [
            "Equal instruction and opcode counts do not prove equal shapes, dependencies, backend configurations, schedule order, buffer offsets, or generated kernels.",
            "Rematerialization counts use only exact XLA instruction names containing `.remat`; JAX checkpoint/remat frontend metadata is not inspected.",
            "Allocation totals sum planned BufferAllocationProto sizes by color; they do not measure physical GPU usage, peak live memory, or allocator fragmentation.",
            "Schedule presence and sequence sizes do not establish identical instruction order.",
        ],
    }
    encoded = json.dumps(result, sort_keys=True, separators=(",", ":")).encode()
    if len(encoded) > MAX_OUTPUT_BYTES:
        raise ValueError(f"bounded output is {len(encoded)} bytes, above {MAX_OUTPUT_BYTES}")
    sys.stdout.buffer.write(encoded + b"\n")


if __name__ == "__main__":
    main()
