from marin.profiling.xplane import _xspace_message_class

MAX_OUTPUT_BYTES = 100_000


def varint(data, position):
    value = 0
    shift = 0
    while True:
        byte = data[position]
        position += 1
        value |= (byte & 0x7F) << shift
        if not byte & 0x80:
            return value, position
        shift += 7


def fields(data):
    position = 0
    result = []
    while position < len(data):
        tag, position = varint(data, position)
        number, wire = tag >> 3, tag & 7
        if wire == 0:
            value, position = varint(data, position)
        elif wire == 1:
            value = data[position : position + 8]
            position += 8
        elif wire == 2:
            length, position = varint(data, position)
            value = data[position : position + length]
            position += length
        elif wire == 5:
            value = data[position : position + 4]
            position += 4
        else:
            raise ValueError(f"unsupported wire type {wire}")
        result.append((number, wire, value))
    return result


def one(items, number, default=None):
    values = [value for field, _, value in items if field == number]
    if not values:
        return default
    if len(values) != 1:
        raise ValueError(f"expected one field {number}, found {len(values)}")
    return values[0]


def many(items, number):
    return [value for field, _, value in items if field == number]


def text(value):
    return value.decode() if value is not None else ""


def packed_ints(items, number):
    result = []
    for field, wire, value in items:
        if field != number:
            continue
        if wire == 0:
            result.append(value)
        elif wire == 2:
            position = 0
            while position < len(value):
                item, position = varint(value, position)
                result.append(item)
        else:
            raise ValueError((number, wire))
    return result


def training_hlo(space):
    matches = []
    for plane in space.planes:
        if plane.name != "/host:metadata":
            continue
        for metadata in plane.event_metadata.values():
            if not metadata.name.startswith("jit_train_step("):
                continue
            payloads = [stat.bytes_value for stat in metadata.stats if stat.bytes_value]
            if len(payloads) == 1:
                matches.append((metadata.name, payloads[0]))
    if len(matches) != 1:
        raise ValueError(f"expected one jit_train_step HloProto, found {[name for name, _ in matches]}")
    return matches[0]


def schedule_summary(module_items):
    payload = one(module_items, 7)
    if payload is None:
        return {"present": False, "sequence_count": 0, "scheduled_instruction_ids": 0}
    entries = many(fields(payload), 1)
    scheduled = 0
    for entry in entries:
        entry_items = fields(entry)
        sequence = one(entry_items, 2)
        if sequence is not None:
            scheduled += len(packed_ints(fields(sequence), 1))
    return {"present": True, "sequence_count": len(entries), "scheduled_instruction_ids": scheduled}


