        for allocation in many(fields(assignment_payload), 3):
            allocation_items = fields(allocation)
            color = str(one(allocation_items, 8, 0))
            color_totals[color]["allocations"] += 1
            color_totals[color]["bytes"] += one(allocation_items, 2, 0)
            allocation_count += 1
