def counter_diff(control, treatment, field):
    left = control[field]
    right = treatment[field]
    return {key: right.get(key, 0) - left.get(key, 0) for key in sorted(set(left) | set(right)) if right.get(key, 0) != left.get(key, 0)}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("control_xplane")
    parser.add_argument("treatment_xplane")
